package isp

import "fmt"

// PROBLEM
//
// WelcomeFat calls exactly one of the ten methods in FatStore, yet it depends
// on all ten. To test it you must build a stand-in with all ten methods, and
// nine of them are fake code that is never used.
//
// TRY IT
//
// Open isp_test.go and look at fakeFat. Count the methods. Nine of them just
// say panic("never called"). That is what testing one function costs today.
//
// Do not edit this file. Your work goes in after.go.

// User and Order are plain data shared by the "before" and "after" code.
type User struct {
	ID   string
	Name string
}

type Order struct {
	ID     string
	UserID string
}

// FatStore is what a database layer typically hands out: everything.
type FatStore interface {
	GetUser(id string) (User, error)
	CreateUser(u User) error
	UpdateUser(u User) error
	DeleteUser(id string) error
	ListUsers() ([]User, error)
	GetOrder(id string) (Order, error)
	CreateOrder(o Order) error
	DeleteOrder(id string) error
	ListOrders(userID string) ([]Order, error)
	Ping() error
}

// WelcomeFat greets the user with the given id.
func WelcomeFat(s FatStore, id string) (string, error) {
	u, err := s.GetUser(id)
	if err != nil {
		return "", fmt.Errorf("welcome %q: %w", id, err)
	}
	return "Welcome, " + u.Name + "!", nil
}
